package icloudcore

import (
	"encoding/base64"
	"encoding/json"
	"testing"

	"howett.net/plist"
)

// makeMediaMetaData builds the base64(binary plist) blob Apple stores in `mediaMetaDataEnc`.
//
// The fixtures are generated by howett.net/plist's encoder rather than being hard-coded byte
// strings: the parser has to cope with whatever a plist writer emits, and hand-transcribed base64
// would make the test depend on one specific serialiser's choices.
func makeMediaMetaData(t *testing.T, props map[string]interface{}) string {
	t.Helper()
	// The format=BinaryFormat flag is what produces the `bplist00` magic the parser requires.
	raw, err := plist.Marshal(props, plist.BinaryFormat)
	if err != nil {
		t.Fatalf("failed to marshal fixture plist: %v", err)
	}
	if len(raw) < 8 || string(raw[:8]) != "bplist00" {
		t.Fatalf("fixture is not a binary plist (magic=%q)", string(raw[:8]))
	}
	return base64.StdEncoding.EncodeToString(raw)
}

// fullProps mirrors what a real iPhone capture looks like: every Apple key the app consumes,
// using the *documented* (unbraced) spellings the parser must accept alongside `{Exif}`.
func fullProps() map[string]interface{} {
	return map[string]interface{}{
		"TIFF": map[string]interface{}{
			"Make":            "Apple",
			"Model":           "iPhone 15 Pro",
			"DateTime":        "2026:10:21 11:03:54",
			"PixelXDimension": int64(4032),
			"PixelYDimension": int64(3024),
			"XResolution":     int64(72),
			"YResolution":     int64(72),
			"ResolutionUnit":  int64(2),
		},
		"Exif": map[string]interface{}{
			"FNumber":            1.85,
			"ExposureTime":       0.001353, // ~1/739s
			"ISOSpeedRatings":    []interface{}{int64(64)},
			"FocalLength":        6.764,
			"FocalLenIn35mmFilm": int64(24),
			"LensModel":          "iPhone 15 Pro back triple camera 6.765mm f/1.78",
			"DateTimeOriginal":   "2026:10:21 11:03:54",
			"BrightnessValue":    5.123,
			"ExposureBiasValue":  -0.3,
		},
		"GPS": map[string]interface{}{
			"Latitude":          36.0671,
			"LatitudeRef":       "N",
			"Longitude":         120.3826,
			"LongitudeRef":      "E",
			"Altitude":          15.5,
			"Speed":             0.0,
			"ImgDirection":      273.4,
			"HPositioningError": 8.0,
			"DateStamp":         "2026:10:21",
			"TimeStamp":         "03:03:54",
		},
		"PNG": map[string]interface{}{
			"ColorModel":  "RGB",
			"ProfileName": "Display P3",
		},
	}
}

// ---------------------------------------------------------------- happy path

func TestDecodeMediaMetaData_FullRecord(t *testing.T) {
	md, ok := decodeMediaMetaData(makeMediaMetaData(t, fullProps()))
	if !ok {
		t.Fatal("expected metadata to decode")
	}
	if !md.HasMetadata {
		t.Error("HasMetadata should be true")
	}

	// Camera body + lens.
	if md.CameraMake != "Apple" {
		t.Errorf("CameraMake = %q, want Apple", md.CameraMake)
	}
	if md.CameraModel != "iPhone 15 Pro" {
		t.Errorf("CameraModel = %q, want iPhone 15 Pro", md.CameraModel)
	}
	if md.LensModel == "" {
		t.Error("LensModel should be populated")
	}

	// Exposure triangle.
	if md.FNumber != 1.85 {
		t.Errorf("FNumber = %v, want 1.85", md.FNumber)
	}
	if md.ExposureTime != 0.001353 {
		t.Errorf("ExposureTime = %v, want 0.001353", md.ExposureTime)
	}
	if md.ISO != 64 {
		t.Errorf("ISO = %d, want 64 (single-element array must unwrap)", md.ISO)
	}
	if md.FocalLength != 6.764 {
		t.Errorf("FocalLength = %v, want 6.764", md.FocalLength)
	}
	if md.FocalLength35 != 24 {
		t.Errorf("FocalLength35 = %v, want 24", md.FocalLength35)
	}
	if md.ExposureBias != -0.3 {
		t.Errorf("ExposureBias = %v, want -0.3", md.ExposureBias)
	}

	// Capture time is passed through verbatim, not reformatted.
	if md.DateTimeOriginal != "2026:10:21 11:03:54" {
		t.Errorf("DateTimeOriginal = %q", md.DateTimeOriginal)
	}

	// Dimensions come from EXIF when present.
	if md.PixelWidth != 4032 || md.PixelHeight != 3024 {
		t.Errorf("dimensions = %dx%d, want 4032x3024", md.PixelWidth, md.PixelHeight)
	}

	if md.ColorModel != "RGB" || md.ProfileName != "Display P3" {
		t.Errorf("colour = %q/%q", md.ColorModel, md.ProfileName)
	}

	if md.Gps == nil {
		t.Fatal("GPS should be present")
	}
	if md.Gps.Latitude != 36.0671 || md.Gps.Longitude != 120.3826 {
		t.Errorf("coords = %v,%v", md.Gps.Latitude, md.Gps.Longitude)
	}
	if md.Gps.Altitude != 15.5 {
		t.Errorf("Altitude = %v, want 15.5", md.Gps.Altitude)
	}
	if md.Gps.ImgDirection != 273.4 {
		t.Errorf("ImgDirection = %v, want 273.4", md.Gps.ImgDirection)
	}
	if md.Gps.Timestamp != "2026:10:21 03:03:54" {
		t.Errorf("Timestamp = %q", md.Gps.Timestamp)
	}
}

// Apple's real payload uses brace-decorated keys (`{Exif}`); the docs use bare ones. Both must
// resolve, because a sample of one spelling is not proof the other never occurs.
func TestDecodeMediaMetaData_BracedKeys(t *testing.T) {
	props := map[string]interface{}{
		"{Exif}": map[string]interface{}{
			"FNumber":     2.2,
			"LensModel":   "Back camera",
			"FocalLength": 2.2,
		},
		"{TIFF}": map[string]interface{}{
			"Make":  "samsung",
			"Model": "Galaxy Z Fold8 Ultra",
		},
		"{GPS}": map[string]interface{}{
			"Latitude":    35.9533637,
			"Longitude":   120.1711042,
			"LatitudeRef": "N",
		},
	}

	md, ok := decodeMediaMetaData(makeMediaMetaData(t, props))
	if !ok {
		t.Fatal("braced keys must decode")
	}
	if md.CameraModel != "Galaxy Z Fold8 Ultra" {
		t.Errorf("CameraModel = %q", md.CameraModel)
	}
	if md.FNumber != 2.2 {
		t.Errorf("FNumber = %v, want 2.2", md.FNumber)
	}
	if md.Gps == nil || md.Gps.Latitude != 35.9533637 {
		t.Errorf("GPS not decoded from braced dict: %+v", md.Gps)
	}
}

// ---------------------------------------------------------------- GPS sign handling

// The single most dangerous bug in this file: EXIF stores magnitude + hemisphere ref, so ignoring
// the ref puts Sydney at 33.87°N and every American photo east of Greenwich.
func TestDecodeMediaMetaData_GpsHemisphereSigns(t *testing.T) {
	cases := []struct {
		name     string
		lat, lng float64
		latRef   string
		lngRef   string
		wantLat  float64
		wantLng  float64
	}{
		{"north-east", 36.06, 120.38, "N", "E", 36.06, 120.38},
		{"south-east (Sydney)", 33.87, 151.21, "S", "E", -33.87, 151.21},
		{"north-west (San Francisco)", 37.77, 122.42, "N", "W", 37.77, -122.42},
		{"south-west (Rio)", 22.91, 43.17, "S", "W", -22.91, -43.17},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			props := map[string]interface{}{
				"GPS": map[string]interface{}{
					"Latitude":     tc.lat,
					"LatitudeRef":  tc.latRef,
					"Longitude":    tc.lng,
					"LongitudeRef": tc.lngRef,
				},
			}
			md, ok := decodeMediaMetaData(makeMediaMetaData(t, props))
			if !ok || md.Gps == nil {
				t.Fatal("GPS should decode")
			}
			if md.Gps.Latitude != tc.wantLat {
				t.Errorf("Latitude = %v, want %v", md.Gps.Latitude, tc.wantLat)
			}
			if md.Gps.Longitude != tc.wantLng {
				t.Errorf("Longitude = %v, want %v", md.Gps.Longitude, tc.wantLng)
			}
		})
	}
}

// A pre-signed negative latitude must not be flipped to positive by an "N" ref.
func TestDecodeMediaMetaData_PreSignedCoordinate(t *testing.T) {
	props := map[string]interface{}{
		"GPS": map[string]interface{}{
			"Latitude":    -33.87,
			"LatitudeRef": "S",
			"Longitude":   151.21,
		},
	}
	md, _ := decodeMediaMetaData(makeMediaMetaData(t, props))
	if md.Gps == nil {
		t.Fatal("GPS should decode")
	}
	if md.Gps.Latitude != -33.87 {
		t.Errorf("pre-signed latitude was corrupted: %v", md.Gps.Latitude)
	}
}

// Equator / prime meridian are legitimate (0,0)-adjacent values, not "missing".
func TestDecodeMediaMetaData_ZeroCoordinateIsValid(t *testing.T) {
	props := map[string]interface{}{
		"GPS": map[string]interface{}{
			"Latitude":  0.0,
			"Longitude": 0.0,
		},
	}
	md, _ := decodeMediaMetaData(makeMediaMetaData(t, props))
	if md.Gps == nil {
		t.Fatal("a 0,0 fix must still produce a GPS block")
	}
}

// ---------------------------------------------------------------- graceful absence

// Screenshots and location-disabled captures have no `{GPS}` at all. Measured: 17 of 25 samples.
func TestDecodeMediaMetaData_NoGPS(t *testing.T) {
	props := map[string]interface{}{
		"TIFF": map[string]interface{}{
			"Model": "Pixel 9",
		},
		"Exif": map[string]interface{}{
			"FNumber": 1.7,
		},
	}

	md, ok := decodeMediaMetaData(makeMediaMetaData(t, props))
	if !ok {
		t.Fatal("metadata without GPS must still decode")
	}
	if md.Gps != nil {
		t.Errorf("Gps should be nil, got %+v", md.Gps)
	}
	if md.CameraModel != "Pixel 9" {
		t.Errorf("other fields must survive: CameraModel = %q", md.CameraModel)
	}
	if md.ISO != 0 {
		t.Errorf("ISO should be 0 (absent), got %d", md.ISO)
	}

	// The JSON must actually omit the key, so Kotlin can use presence as the signal.
	blob, _ := json.Marshal(md)
	var generic map[string]interface{}
	_ = json.Unmarshal(blob, &generic)
	if _, present := generic["gps"]; present {
		t.Error("gps key must be omitted from JSON when absent")
	}
}

// A screenshot: metadata may exist (PNG block) but be nearly empty. This must not be an error.
func TestDecodeMediaMetaData_ScreenshotLike(t *testing.T) {
	props := map[string]interface{}{
		"PNG": map[string]interface{}{
			"DPIWidth":    int64(480),
			"DPIHeight":   int64(480),
			"ColorModel":  "RGB",
			"ProfileName": "sRGB IEC61966-2.1",
		},
	}
	md, ok := decodeMediaMetaData(makeMediaMetaData(t, props))
	if !ok {
		t.Fatal("PNG-only metadata must decode")
	}
	if md.ColorModel != "RGB" {
		t.Errorf("ColorModel = %q", md.ColorModel)
	}
	if md.CameraModel != "" || md.Gps != nil {
		t.Error("camera/GPS fields should be absent")
	}
}

func TestDecodeMediaMetaData_MissingField(t *testing.T) {
	if _, ok := decodeMediaMetaData(""); ok {
		t.Error("blank field must report no metadata")
	}
	if _, ok := decodeMediaMetaData("   "); ok {
		t.Error("whitespace-only field must report no metadata")
	}
}

// Third-party imports carry garbage or nothing. Every one of these must be a quiet "no metadata",
// never a panic and never a request failure.
func TestDecodeMediaMetaData_CorruptInputs(t *testing.T) {
	if _, ok := decodeMediaMetaData("!!!not-base64!!!"); ok {
		t.Error("garbage base64 must report no metadata")
	}

	// Valid base64, wrong magic bytes (e.g. an XML plist or a JPEG preview).
	notPlist := base64.StdEncoding.EncodeToString([]byte(`<?xml version="1.0"?><plist></plist>`))
	if _, ok := decodeMediaMetaData(notPlist); ok {
		t.Error("non-bplist payload must report no metadata")
	}

	// Correct magic, truncated body — must not panic inside plist.Unmarshal.
	truncated := base64.StdEncoding.EncodeToString([]byte("bplist00\x00\x01\x02"))
	if _, ok := decodeMediaMetaData(truncated); ok {
		t.Error("truncated plist must report no metadata")
	}
}

// ---------------------------------------------------------------- batch endpoint

// FetchPhotoMetadata must degrade to a structured AUTH_EXPIRED (not a panic) with no session, and
// must never report "metadata missing" as a failure — that is the contract the Kotlin side relies
// on to cache negative results.
func TestFetchPhotoMetadata_NoSession(t *testing.T) {
	resetSessionForTest()

	var out MetadataResult
	if err := json.Unmarshal([]byte(FetchPhotoMetadata(`["m1"]`)), &out); err != nil {
		t.Fatalf("response must be valid JSON: %v", err)
	}
	if out.Success {
		t.Error("expected failure without a session")
	}
	if out.ErrorCode != ErrCodeAuthExpired {
		t.Errorf("ErrorCode = %q, want %q", out.ErrorCode, ErrCodeAuthExpired)
	}
	if out.Items == nil {
		t.Error("Items must be non-nil so the client need not null-check")
	}
}

func TestFetchPhotoMetadata_BadInput(t *testing.T) {
	resetSessionForTest()

	var out MetadataResult
	if err := json.Unmarshal([]byte(FetchPhotoMetadata(`not json`)), &out); err != nil {
		t.Fatalf("response must be valid JSON: %v", err)
	}
	// No session is checked first, so this asserts the ordering is at least sane: we get a
	// structured error rather than a panic.
	if out.Success {
		t.Error("expected failure")
	}
}

// resetSessionForTest clears the process-global session so tests are order-independent.
func resetSessionForTest() {
	sessionMu.Lock()
	currentSession = nil
	sessionMu.Unlock()
}
